// Generated by esquadro: do not edit. A filter by a period of a date
// (created_at, or a date field the API filters): presets (today, the last
// 7 or 30 days, this month) or a range picked in the calendar, with
// shadcn/ui's Popover and Calendar.
import { Calendar as CalendarIcon, X } from "../icons.gen.ts"
import { useState } from "react"
import type { DateRange } from "react-day-picker"
import { ptBR } from "date-fns/locale"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { locale } from "../config.ts"
import { t } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"

const DAY = 86_400_000

function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

function endOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999)
}

/** The presets, each a start (and no end: up to now). */
function presets(): { key: string; label: string; from: Date }[] {
  const today = startOfDay(new Date())
  return [
    { key: "today", label: t("today"), from: today },
    { key: "7d", label: t("last7days"), from: new Date(today.getTime() - 6 * DAY) },
    { key: "30d", label: t("last30days"), from: new Date(today.getTime() - 29 * DAY) },
    { key: "month", label: t("thisMonth"), from: new Date(today.getFullYear(), today.getMonth(), 1) },
  ]
}

/** A moment as the API takes it: a date for a date field, else an instant. */
export function param(field: FieldMeta, d: Date): string {
  if (field.kind === "date") {
    const p = (n: number) => String(n).padStart(2, "0")
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
  }
  return d.toISOString()
}

function parse(value?: string): Date | undefined {
  if (!value) return undefined
  const d = new Date(value.length === 10 ? `${value}T00:00:00` : value)
  return Number.isNaN(d.getTime()) ? undefined : d
}

const day = (d: Date) => new Intl.DateTimeFormat(locale, { day: "2-digit", month: "short" }).format(d)

/** What a period reads: "Last 7 days", "02 Nov – 10 Nov", "since 02 Nov", or All. */
export function periodSummary(min?: string, max?: string): string {
  const from = parse(min)
  const to = parse(max)
  const preset = !to && from ? presets().find((p) => startOfDay(from).getTime() === p.from.getTime()) : undefined
  return preset ? preset.label : from ? (to ? `${day(from)} – ${day(to)}` : `${t("since")} ${day(from)}`) : t("all")
}

/**
 * The period's button and its popover. Bare, it fills its place and leaves
 * the field's name to a label above it (in a drawer, a dialog).
 */
export function DateRangeFilter({
  field,
  min,
  max,
  onChange,
  bare = false,
}: {
  field: FieldMeta
  min?: string
  max?: string
  onChange: (min?: string, max?: string) => void
  bare?: boolean
}) {
  const [open, setOpen] = useState(false)
  const from = parse(min)
  const to = parse(max)
  const [range, setRange] = useState<DateRange | undefined>({ from, to })
  const preset = !to && from ? presets().find((p) => startOfDay(from).getTime() === p.from.getTime()) : undefined
  const summary = periodSummary(min, max)
  const apply = (f?: Date, e?: Date) => {
    onChange(f && param(field, startOfDay(f)), e && param(field, field.kind === "date" ? startOfDay(e) : endOfDay(e)))
    setOpen(false)
  }
  return (
    <Popover
      open={open}
      onOpenChange={(o) => {
        setOpen(o)
        // A period with no end runs up to today.
        if (o) setRange({ from, to: to ?? (from ? new Date() : undefined) })
      }}
    >
      <PopoverTrigger asChild>
        <Button variant="outline" id={bare ? `filter-${field.name}` : undefined} className={cn("justify-start font-normal", bare && "h-11 w-full rounded-lg border-transparent bg-input px-3 font-semibold shadow-none hover:bg-input/80 dark:bg-input dark:hover:bg-input/80", !from && "text-muted-foreground")}>
          <CalendarIcon />
          {!bare && <span className="text-muted-foreground">{field.label}:</span>}
          <span className={cn("text-foreground", bare && !from && "text-muted-foreground")}>{summary}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="flex w-auto flex-col gap-2 p-2 sm:flex-row" align="start">
        <div className="flex flex-row flex-wrap gap-1 sm:w-40 sm:flex-col">
          {presets().map((p) => (
            <Button
              key={p.key}
              variant={preset?.key === p.key ? "secondary" : "ghost"}
              size="sm"
              className="justify-start"
              onClick={() => apply(p.from)}
            >
              {p.label}
            </Button>
          ))}
          {from && (
            <Button variant="ghost" size="sm" className="justify-start text-muted-foreground" onClick={() => apply()}>
              <X /> {t("clearPeriod")}
            </Button>
          )}
        </div>
        <div className="flex flex-col gap-2">
          <Calendar
            mode="range"
            numberOfMonths={2}
            // Two months, the period's end (or this month) on the right.
            defaultMonth={new Date((to ?? new Date()).getFullYear(), (to ?? new Date()).getMonth() - 1, 1)}
            selected={range}
            onSelect={setRange}
            locale={locale === "pt-BR" ? ptBR : undefined}
            disabled={{ after: new Date() }}
          />
          <div className="flex justify-end gap-2 px-2 pb-1">
            <Button variant="outline" size="sm" onClick={() => setOpen(false)}>
              {t("cancel")}
            </Button>
            <Button size="sm" disabled={!range?.from} onClick={() => apply(range?.from, range?.to ?? range?.from)}>
              {t("apply")}
            </Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}
